import os,glob,re,json
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))
inp=G['Demo pair 1 input']; out=G['Demo pair 1 output']
for r in range(len(inp)):
    for c in range(len(inp[0])):
        if inp[r][c]!=out[r][c]:
            print('change',r,c,'->',inp[r][c],'->',out[r][c])

from collections import deque
def solve(g,bg,outv=4):
    h,w=len(g),len(g[0])
    seen=[[False]*w for _ in range(h)]
    q=deque()
    for i in range(h):
        for j in (0,w-1):
            if g[i][j]==bg: seen[i][j]=True; q.append((i,j))
    for j in range(w):
        for i in (0,h-1):
            if g[i][j]==bg: seen[i][j]=True; q.append((i,j))
    while q:
        i,j=q.popleft()
        for di,dj in ((1,0),(-1,0),(0,1),(0,-1)):
            a,b=i+di,j+dj
            if 0<=a<h and 0<=b<w and g[a][b]==bg and not seen[a][b]:
                seen[a][b]=True; q.append((a,b))
    return [[outv if (g[i][j]==bg and not seen[i][j]) else g[i][j] for j in range(w)] for i in range(h)]
r=solve(inp)
print(r==out)
res=solve(G['Test input'])
for row in res[:4]: print(row)

